	router.POST(options.BaseURL+"/auth/oauth/exchange", wrapper.ExchangeOAuth, options.OperationMiddlewares["exchangeOAuth"]...)
	router.POST(options.BaseURL+"/auth/native/:provider/nonce", wrapper.IssueNativeNonce, options.OperationMiddlewares["issueNativeNonce"]...)
	router.POST(options.BaseURL+"/auth/native/:provider/login", wrapper.NativeLogin, options.OperationMiddlewares["nativeLogin"]...)
	router.POST(options.BaseURL+"/auth/session/refresh", wrapper.RefreshSession, options.OperationMiddlewares["refreshSession"]...)
	router.POST(options.BaseURL+"/auth/session/logout", wrapper.Logout, options.OperationMiddlewares["logout"]...)
